'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var join = require( 'path' ).join;
var existsSync = require( 'fs' ).existsSync;
var logger = require( 'debug' );
var writeFile = require( '@stdlib/fs/write-file' ).sync;
var namespace = require( '@stdlib/namespace' );


// VARIABLES //

var debug = logger( 'namespace:packages:build' );

// Root of the monorepo node_modules directory (lib/node_modules):
var LIB_DIR = resolve( __dirname, '..', '..', '..', '..', '..' );

// Output file path:
var OUTPUT_JSON = resolve( __dirname, '..', 'data', 'data.json' );


// FUNCTIONS //

/**
* Returns the description for a package by reading its package.json.
*
* @private
* @param {string} pkgDir - absolute path to the package directory
* @returns {string} package description, or empty string if not found
*/
function getDescription( pkgDir ) {
	var pkgJSON;
	var fpath;
	fpath = join( pkgDir, 'package.json' );
	if ( !existsSync( fpath ) ) {
		return '';
	}
	try {
		pkgJSON = require( fpath ); // eslint-disable-line stdlib/no-dynamic-require
		return pkgJSON.description || '';
	} catch ( err ) {
		debug( 'WARNING: unable to read package.json for %s: %s', pkgDir, err.message );
		return '';
	}
}

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var pkgDir;
	var fopts;
	var entry;
	var json;
	var ns;
	var i;

	debug( 'Extracting namespace package data...' );
	ns = namespace();
	json = {};
	for ( i = 0; i < ns.length; i++ ) {
		entry = ns[ i ];
		pkgDir = join( LIB_DIR, 'node_modules', entry.path );

		json[ entry.path ] = {
			'alias': entry.alias,
			'description': getDescription( pkgDir ),
			'type': entry.type,
			'related': entry.related,
			'hasCliTool': existsSync( join( pkgDir, 'bin', 'cli' ) ),
			'hasNativeAddon': existsSync( join( pkgDir, 'binding.gyp' ) ),
			'hasWasm': existsSync( join( pkgDir, 'src', 'main.wasm' ) )
		};
	}

	debug( 'Writing to JSON file...' );
	fopts = {
		'encoding': 'utf8'
	};
	writeFile( OUTPUT_JSON, JSON.stringify( json, null, '\t' )+'\n', fopts );

	debug( 'Done. Wrote %d entries to %s', ns.length, OUTPUT_JSON );
	console.log( 'Generated package catalog with %d entries.', ns.length ); // eslint-disable-line no-console
}


// MAIN //

main();
